use sonic_playground::fire_effect::{FireEffects,Spawn};use sa2_runtime::original_math::OriginalMath;
fn math()->OriginalMath{OriginalMath::from_data_bundle(include_bytes!("../assets/original-math-data.bin").to_vec()).unwrap()}
#[test]fn stream_is_bounded_and_all_particles_expire(){let m=math();let mut fx=FireEffects::default();for _ in 0..120{fx.tick(Some(Spawn{player:0,center:[0.,5.,0.],velocity:[4.,0.,0.]}),&m).unwrap();assert!(fx.records().len()<=14);assert_eq!(fx.visible().count(),fx.records().len());}assert_eq!(fx.spawned,120);for _ in 0..14{fx.tick(None,&m).unwrap();}assert!(fx.records().is_empty());}
#[test]fn failed_spawn_preserves_existing_particles_and_rng(){let m=math();let mut fx=FireEffects::default();fx.tick(Some(Spawn{player:0,center:[0.;3],velocity:[1.,0.,0.]}),&m).unwrap();let before=fx.clone();assert!(fx.tick(Some(Spawn{player:2,center:[0.;3],velocity:[1.,0.,0.]}),&m).is_err());assert_eq!(fx.records(),before.records());assert_eq!(fx.seed(),before.seed());assert_eq!(fx.spawned,before.spawned);}
#[test]fn zero_velocity_has_original_first_frame_then_is_not_drawable(){let m=math();let mut fx=FireEffects::default();fx.tick(Some(Spawn{player:0,center:[0.;3],velocity:[0.;3]}),&m).unwrap();assert_eq!(fx.visible().count(),1);fx.tick(None,&m).unwrap();assert_eq!(fx.visible().count(),0);assert_eq!(fx.records().len(),1);for _ in 0..14{fx.tick(None,&m).unwrap();}assert!(fx.records().is_empty());}

#[test]fn billboard_uses_source_descriptor_scale_and_sequence(){let mut data=[0u8;32];data[16..20].copy_from_slice(&10f32.to_be_bytes());data[28..32].copy_from_slice(&0.2f32.to_be_bytes());for age in 0i16..14{data[2..4].copy_from_slice(&age.to_be_bytes());let b=sonic_playground::fire_effect::billboard(&data).unwrap();assert_eq!(b.texture,(age/2)as usize);assert!((b.half_extent-0.32).abs()<1e-6);assert_eq!(b.center.x,1.);}data[2..4].copy_from_slice(&14i16.to_be_bytes());assert!(sonic_playground::fire_effect::billboard(&data).is_none());}

#[test]fn player_somersault_emits_and_recovery_stops(){use sonic_playground::simulation::{Player,Input};let mut p=Player::new();let mut fx=FireEffects::default();p.tick(Input{bounce_pressed:true,..Default::default()});fx.tick_player(&p).unwrap();assert_eq!(fx.spawned,1);for _ in 0..120{p.tick(Input::default());fx.tick_player(&p).unwrap();}assert!(fx.spawned>1);assert!(fx.records().is_empty());let spawned=fx.spawned;for _ in 0..20{p.tick(Input::default());fx.tick_player(&p).unwrap();}assert_eq!(fx.spawned,spawned);p.reset();fx.tick_player(&p).unwrap();assert!(fx.records().is_empty());}
